def minPath(grid, k):
    from heapq import heappush, heappop
    import heapq

    n = len(grid)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    heap = []

    for i in range(n):
        for j in range(n):
            path = [grid[i][j]]
            heappush(heap, (path, i, j, 0))

    while heap:
        path, x, y, steps = heappop(heap)
        if steps == k:
            return path
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n:
                new_path = path + [grid[nx][ny]]
                heapq.heappush(heap, (new_path, nx, ny, steps + 1))

