        (10, 'x'), (9, 'ix'), (5, 'v'), (4, 'iv'),
        (1, 'i')
    ]
    res = ''
    for (num, roman) in val:
        while number >= num:
            res += roman
            number -= num
    return res

def right_angle_triangle(a, b, c):
    sides = sorted([a, b, c])
    return sides[0]**2 + sides[1]**2 == sides[2]**2

def find_max(words):
    max_unique = -1
    result = ""
    for word in words:
        unique_chars = len(set(word))
        if unique_chars > max_unique or (unique_chars == max_unique and word < result):
            max_unique = unique_chars
            result = word
    return result

def do_algebra(operator, operand):
    result = operand[0]
    for i in range(len(operator)):
        if operator[i] == '+':
            result += operand[i+1]
        elif operator[i] == '-':
            result -= operand[i+1]
        elif operator[i] == '*':
            result *= operand[i+1]
        elif operator[i] == '//':
            result //= operand[i+1]
        elif operator[i] == '**':
            result **= operand[i+1]
    return result

def solve(s):
    has_letter = any(c.isalpha() for c in s)
    if not has_letter:
        return s[::-1]
    result = []
    for c in s:
        if c.isalpha():
            result.append(c.upper() if c.islower() else c.lower())
        else:
            result.append(c)
    return ''.join(result)

def string_to_md5(text):
    """
    Given a string 'text', return its md5 hash equivalent string.
    If 'text' is an empty string, return None.

    >>> string_to_md5('Hello world') == '3e25960a79dbc69b674cd4ec67a72c62'
    """
    if not text:
        return None
    import hashlib
    return hashlib.md5(text.encode()).hexdigest()

def generate_integers(a, b):
    start = min(a, b)
    end = max(a, b)
    return [i for i in range(start, end + 1) if len(str(i)) % 2 == 0]
